function lineChart(canvasId,series,colors,height=220){const canvas=$(canvasId);if(!canvas)return;const ctx=canvas.getContext('2d'),scale=devicePixelRatio||1,width=canvas.clientWidth||600;canvas.width=width*scale;canvas.height=height*scale;ctx.scale(scale,scale);ctx.clearRect(0,0,width,height);const all=series.flatMap(s=>s.values).filter(Number.isFinite);if(all.length<2){ctx.fillStyle='#777';ctx.fillText('Not enough comparable results yet',15,36);return}const min=Math.min(...all),max=Math.max(...all),span=max-min||1;ctx.strokeStyle='#ddd8ca';ctx.lineWidth=1;for(let i=0;i<5;i++){const y=18+i*(height-40)/4;ctx.beginPath();ctx.moveTo(8,y);ctx.lineTo(width-8,y);ctx.stroke()}series.forEach((s,index)=>{ctx.strokeStyle=colors[index%colors.length];ctx.lineWidth=2.3;ctx.beginPath();s.values.forEach((v,i)=>{if(!Number.isFinite(v))return;const x=12+i*(width-24)/Math.max(1,s.values.length-1),y=height-22-(v-min)/span*(height-45);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()})}
