async function loadLabComparison(){const code=$('labAnalyte')?.value;if(!code)return;try{state.labComparison=await api(`api/v1/labs/comparison?analyte_code=${encodeURIComponent(code)}&from_year=2020&to_year=${state.year}`);drawLabChart();renderLabTrends()}catch(error){toast(error.message)}}
function drawLabChart(){const colors=['#8a713e','#4f7d5b','#a85343','#597da1','#8e6496'],groups={};state.labComparison.forEach(row=>{const key=row.wine_lot_code||row.variety_name||row.sample_name;groups[key]??=[];groups[key].push(row)});const series=Object.entries(groups).map(([name,rows])=>({name,values:rows.map(r=>Number(r.numeric_value))}));$('labLegend').innerHTML=series.map((s,i)=>`<span><i style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${colors[i%colors.length]};margin-right:4px"></i>${esc(s.name)}</span>`).join('');lineChart('labChart',series,colors,240)}
function renderLabTrends(){const trends=state.labTrends||{annual:[],coverage:[]},coverage=trends.coverage||[],annual=trends.annual||[],current=coverage.filter(row=>Number(row.result_year)===state.year),samples=current.reduce((sum,row)=>sum+Number(row.sample_count||0),0),reviews=current.reduce((sum,row)=>sum+Number(row.review_count||0),0),analytes=new Set(annual.map(row=>row.analyte_code)).size,years=new Set(coverage.map(row=>row.result_year)).size;$('labCoverage').innerHTML=`<article class="metric"><span>${state.year} samples</span><strong>${samples}</strong></article><article class="metric"><span>Need review</span><strong>${reviews}</strong></article><article class="metric"><span>Analytes tracked</span><strong>${analytes}</strong></article><article class="metric"><span>Years covered</span><strong>${years}</strong></article>`;const selected=$('labAnalyte')?.value,rows=annual.filter(row=>!selected||row.analyte_code===selected);$('labAnnualTable').innerHTML=rows.length?`<div class="trend-head"><b>Year</b><b>Sample</b><b>Average</b><b>Range</b><b>Count</b></div>${rows.map(row=>`<div class="trend-row"><b>${row.result_year}</b><span>${esc(row.sample_type)}</span><strong>${fmt(row.average_value)} ${esc(row.unit||'')}</strong><span>${fmt(row.minimum_value)}–${fmt(row.maximum_value)}</span><span>${row.result_count}${row.flagged_count?' · '+row.flagged_count+' flagged':''}</span></div>`).join('')}`:'No annual trend data for this analyte.'}
function renderPressure(){const rows=(state.pressure||[]).filter((row,index,array)=>array.findIndex(other=>other.disease_code===row.disease_code)===index);const node=$('pressureCards');if(!node)return;node.innerHTML=rows.map(row=>`<article class="pressure-card risk-${row.risk_level}"><span>${esc(row.risk_level)}</span><strong>${esc(row.disease_name)}</strong><b>${fmt(row.risk_score)}</b><small>${esc(row.suggested_action)}</small><em>${esc((row.agronomist_status||'pending').replace('_',' '))}</em></article>`).join('')||'<article class="panel">Waiting for weather observations.</article>'}
function renderTreatments(){const rows=state.treatments||[],planned=rows.filter(r=>r.status==='planned').length,done=rows.filter(r=>r.status==='completed').length,approved=rows.filter(r=>r.agronomist_approved).length;$('treatmentSummary').innerHTML=`<article class="metric"><span>Planned</span><strong>${planned}</strong></article><article class="metric"><span>Completed</span><strong>${done}</strong></article><article class="metric"><span>Agronomist approved</span><strong>${approved}</strong></article><article class="metric"><span>Records</span><strong>${rows.length}</strong></article>`;$('treatmentList').classList.toggle('empty',!rows.length);$('treatmentList').innerHTML=rows.length?rows.map(row=>`<div class="list-row ${row.status==='planned'?'urgent':''}"><span class="list-icon">♧</span><div><b>${esc(row.purpose)}</b><small>${esc(row.block_code||'All blocks')} · ${esc(row.products||'Product not entered')} · ${esc(row.status)}</small></div><time>${new Date(row.application_date).toLocaleDateString()}</time></div>`).join(''):'No treatment records.'}
function alertRows(rows,withActions=false){return rows.map(row=>`<div class="list-row ${row.severity==='critical'||row.severity==='warning'?'urgent':''}"><span class="list-icon">!</span><div><b>${esc(row.title)}</b><small>${esc(row.message)}${withActions&&state.session?.permissions?.write?` <button class="text-button" data-alert-resolve="${row.id}">Resolve</button>`:''}</small></div><time>${new Date(row.triggered_at).toLocaleDateString()}</time></div>`).join('')}
function renderAlerts(){const rows=state.alerts||[];for(const id of ['todayAlerts','alertList']){const node=$(id);if(!node)continue;node.classList.toggle('empty',!rows.length);node.innerHTML=rows.length?alertRows(rows,id==='alertList'):'No active alerts.'}document.querySelectorAll('[data-alert-resolve]').forEach(button=>button.onclick=async()=>{await api(`api/v1/alerts/${button.dataset.alertResolve}`,{method:'PATCH',body:JSON.stringify({status:'resolved'})});await loadAll()})}
function renderIntake(){const rows=state.intake||[],node=$('intakeList');if(!node)return;node.classList.toggle('empty',!rows.length);node.innerHTML=rows.length?rows.map(row=>`<div class="list-row"><span class="list-icon">${row.source==='gmail'?'✉':'□'}</span><div><b>${esc(row.title||row.original_filename||'Incoming item')}</b><small>${esc(row.source)} · ${esc((row.classification||'unclassified').replace('_',' '))} · ${esc(row.review_status.replaceAll('_',' '))}${row.ai_summary?' · '+esc(row.ai_summary):''}${state.session?.permissions?.write&&row.review_status==='new'?` <button class="text-button" data-analyze="${row.id}">Analyze</button>`:''}</small></div><time>${new Date(row.received_at).toLocaleDateString()}</time></div>`).join(''):'No incoming items.';document.querySelectorAll('[data-analyze]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const result=await api(`api/v1/intake/${button.dataset.analyze}/analyze`,{method:'POST',body:'{}'});toast(result.configured?'Analysis ready':result.message);await loadAll()}catch(error){toast(error.message)}finally{button.disabled=false}})}
function renderLabHistory(){const rows=state.labHistory||[],node=$('labHistoryList');if(!node)return;node.classList.toggle('empty',!rows.length);node.innerHTML=rows.length?rows.map(row=>`<button class="history-row" data-lab-sample="${row.sample_id}"><span><b>${esc(row.sample_name)}</b><small>${esc(row.sample_type)} · ${esc(row.laboratory||'Laboratory not recorded')} · ${row.result_count} results</small><small>${esc(row.results_summary||'')}</small></span><time>${new Date(`${row.lab_date}T12:00:00`).toLocaleDateString()}</time></button>`).join(''):'No laboratory history.';document.querySelectorAll('[data-lab-sample]').forEach(button=>button.onclick=()=>openLabSample(button.dataset.labSample))}
async function openLabSample(id){try{const detail=await api(`api/v1/labs/samples/${id}`);$('labDialogTitle').textContent=detail.sample.sample_name;$('labDetail').innerHTML=detail.results.map(result=>`<div class="lab-result-row"><div><b>${esc(result.analyte_name)}</b><small>${esc(result.analyte_code)}${result.method?' · '+esc(result.method):''}</small></div><strong>${esc(result.numeric_value??result.text_value??'—')} ${esc(result.unit||'')}</strong>${state.session?.permissions?.write?`<button data-edit-result="${result.id}" data-value="${esc(result.numeric_value??'')}" data-unit="${esc(result.unit||'')}">Correct</button>`:''}</div>`).join('')+(detail.revisions.length?`<details><summary>Correction history (${detail.revisions.length})</summary>${detail.revisions.map(r=>`<p><b>${esc(r.changed_by)}</b> · ${new Date(r.changed_at).toLocaleString()}<br>${esc(r.reason)}</p>`).join('')}</details>`:'');$('labDialog').showModal();document.querySelectorAll('[data-edit-result]').forEach(button=>button.onclick=()=>correctLabResult(button,id))}catch(error){toast(error.message)}}
async function correctLabResult(button,sampleId){const value=prompt('Correct numeric value',button.dataset.value);if(value===null)return;const unit=prompt('Unit',button.dataset.unit);if(unit===null)return;const reason=prompt('Why is this being corrected?');if(!reason)return toast('A correction reason is required');try{await api(`api/v1/labs/results/${button.dataset.editResult}`,{method:'PATCH',body:JSON.stringify({numeric_value:value===''?null:Number(value),unit,reason})});toast('Correction saved with audit history');await openLabSample(sampleId);await loadAll()}catch(error){toast(error.message)}}
function drawWeatherComparison(){const measure=$('weatherMeasure')?.value||'temp_avg_c',colors=['#d4af37','#4f7d5b','#a85343','#597da1','#8e6496'],groups={};for(const row of state.weatherComparison||[]){groups[row.weather_year]??=Array(12).fill(null);groups[row.weather_year][Number(row.weather_month)-1]=row[measure]==null?null:Number(row[measure])}const series=Object.entries(groups).map(([name,values])=>({name,values}));$('weatherLegend').innerHTML=series.map((s,i)=>`<span><i style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${colors[i%colors.length]};margin-right:4px"></i>${s.name}</span>`).join('');lineChart('weatherCompareChart',series,colors,240)}
async function openRecords(type){try{const rows=await api(`api/v1/records/${type}`);$('recordDialogTitle').textContent=type[0].toUpperCase()+type.slice(1);$('recordDialogList').innerHTML=type==='attachments'?(rows.length?rows.map(row=>`<a class="attachment-card" href="api/v1/attachments/${row.id}/file" target="_blank" rel="noopener"><span class="attachment-preview">${String(row.media_type||'').startsWith('image/')?`<img src="api/v1/attachments/${row.id}/file" alt="${esc(row.caption||row.original_filename)}" loading="lazy">`:'PDF'}</span><span><b>${esc(row.caption||row.original_filename)}</b><small>${esc(row.entity_type.replaceAll('_',' '))} · ${esc(row.uploaded_by||'unknown')} · ${new Date(row.created_at).toLocaleDateString()}</small></span></a>`).join(''):'<div class="list empty">No photo evidence.</div>'):(rows.length?rows.map(row=>`<div class="record-data-row">${Object.entries(row).filter(([,value])=>value!==null&&value!=='').map(([key,value])=>`<span><small>${esc(key.replaceAll('_',' '))}</small><b>${esc(value)}</b></span>`).join('')}</div>`).join(''):'<div class="list empty">No records.</div>');$('recordDialog').showModal()}catch(error){toast(error.message)}}
const financeDocumentFields=type=>`<input type="hidden" name="document_type" value="${type}"><div class="field-row"><div class="field"><label>Invoice number</label><input name="document_number" required></div><div class="field"><label>Date</label><input type="date" name="document_date" required value="${today()}"></div></div><div class="field"><label>${type==='sales_invoice'?'Customer':'Supplier'}</label><input name="party_name" required></div><div class="field-row"><div class="field"><label>Net amount</label><input type="number" step="0.01" min="0" name="taxable_amount" required></div><div class="field"><label>VAT</label><input type="number" step="0.01" min="0" name="vat_amount" value="0"></div></div><div class="field"><label>Payment</label><select name="payment_status"><option value="unknown">Unknown</option><option value="unpaid">Unpaid</option><option value="paid">Paid</option><option value="part_paid">Part paid</option></select></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
const fields={task:()=>`<div class="field"><label>Task</label><input name="title" required placeholder="Prune upper block"></div><div class="field-row"><div class="field"><label>Due date</label><input type="date" name="due_date" value="${today()}"></div>${blockField()}</div>${categoryField()}<div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`,activity:()=>`<div class="field"><label>Work completed</label><input name="title" required placeholder="Mowed between rows"></div><div class="field-row"><div class="field"><label>Date</label><input type="date" name="activity_date" required value="${today()}"></div>${blockField()}</div>${categoryField()}<div class="field-row"><div class="field"><label>Hours</label><input type="number" step="0.25" min="0" name="labor_hours"></div><div class="field"><label>People</label><input type="number" min="0" name="worker_count"></div></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`,harvest:()=>`<div class="field"><label>Variety</label><select name="variety_id" required><option value="">Choose…</option>${state.reference.varieties.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></div><div class="field-row"><div class="field"><label>Date & time</label><input type="datetime-local" name="harvested_at" required value="${today()}T08:00"></div>${blockField()}</div><div class="field-row"><div class="field"><label>Weight (kg)</label><input type="number" step="0.1" min="0" name="weight_kg"></div><div class="field"><label>Crates</label><input type="number" min="0" name="crate_count"></div></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`};
