fields.scouting=()=>`${blockField()}<div class="field-row"><div class="field"><label>Date & time</label><input type="datetime-local" name="observed_at" required value="${today()}T12:00"></div><div class="field"><label>Severity</label><select name="severity"><option>trace</option><option selected>low</option><option>medium</option><option>high</option><option>critical</option></select></div></div><div class="field"><label>What did you see?</label><input name="issue_type" required placeholder="Mildew, hail, pests, water stress…"></div><div class="field"><label>Location detail</label><input name="location_note"></div><div class="field"><label><input type="checkbox" name="action_required"> Action is needed</label></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
