fields.lab=()=>`<div class="field-row"><div class="field"><label>Sample date</label><input type="date" name="lab_date" required value="${today()}"></div><div class="field"><label>Sample type</label><select name="sample_type"><option>grape</option><option>must</option><option selected>wine</option><option>soil</option><option>water</option><option>other</option></select></div></div><div class="field"><label>Sample / lot name</label><input name="sample_name" required></div><div class="field-row"><div class="field"><label>Analyte</label><input name="analyte_name" required placeholder="pH, TA, VA, SO₂…"></div><div class="field"><label>Code</label><input name="analyte_code" required placeholder="ph, ta, va…"></div></div><div class="field-row"><div class="field"><label>Value</label><input type="number" step="0.0001" name="numeric_value" required></div><div class="field"><label>Unit</label><input name="unit"></div></div><div class="field"><label>Laboratory / source</label><input name="laboratory"></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
