function blockField(){return `<div class="field"><label>Block</label><select name="block_id"><option value="">All / none</option>${(state.reference?.blocks||[]).map(b=>`<option value="${b.id}">${esc(b.code)} — ${esc(b.name)}</option>`).join('')}</select></div>`}function categoryField(){return `<div class="field"><label>Category</label><select name="category">${state.reference.categories.map(c=>`<option value="${c}">${c.replace('_',' ')}</option>`).join('')}</select></div>`}
function openEntry(type){state.entry=type;const titles={task:'Plan a task',activity:'Log work',harvest:'Add harvest lot',purchase:'Add purchase invoice',sale:'Add sales invoice',cash:'Record cash movement',cellar:'Cellar operation',scouting:'Scouting observation',phenology:'Growth stage',treatment:'Treatment record',lab:'Laboratory result',labor:'Labor hours',inventory:'Inventory count',olive:'Olive record',issue:'Issue or decision'},photoTypes=new Set(['activity','harvest','cellar','scouting','phenology','treatment','lab','labor','olive','issue']);$('dialogTitle').textContent=titles[type];$('formFields').innerHTML=fields[type]()+(!photoTypes.has(type)?'':`<div class="field photo-field"><label>Photos or supporting document (optional)</label><input type="file" name="attachments" accept="image/*,.pdf" multiple><small>Add a field photo, screenshot, instruction, timesheet or report to this record.</small></div>`);$('entryDialog').showModal()}
function closeEntry(){if($('entryDialog').open)$('entryDialog').close('cancel')}
async function saveEntry(event){event.preventDefault();const form=new FormData(event.target),attachments=form.getAll('attachments').filter(file=>file instanceof File&&file.size);form.delete('attachments');const payload=Object.fromEntries(form.entries());for(const box of event.target.querySelectorAll('input[type=checkbox]'))payload[box.name]=box.checked;for(const key of Object.keys(payload))if(payload[key]==='')payload[key]=null;['labor_hours','worker_count','weight_kg','crate_count','taxable_amount','vat_amount','withholding_tax','amount_in','amount_out','amount','temp_c','incidence_pct','percent_complete','dose_amount','total_used','phi_days','regular_hours','hourly_rate_eur','quantity_on_hand','olives_harvested_kg','oil_liters','numeric_value'].forEach(key=>{if(payload[key]!=null)payload[key]=Number(payload[key])});const routes={task:'tasks',activity:'activities',harvest:'harvest',purchase:'finance/documents',sale:'finance/documents',cash:'finance/cash',cellar:'quick-entry/cellar_operation',scouting:'quick-entry/scouting',phenology:'quick-entry/phenology',treatment:'quick-entry/treatment',labor:'quick-entry/labor',inventory:'quick-entry/inventory_count',olive:'quick-entry/olive',issue:'quick-entry/issue'},attachmentTypes={activity:'activity',harvest:'harvest',cellar:'cellar_operation',scouting:'scouting',phenology:'phenology',treatment:'treatment',lab:'lab_sample',labor:'labor',olive:'olive',issue:'issue'};if(state.entry==='lab'){payload.results=[{analyte_code:payload.analyte_code,analyte_name:payload.analyte_name,numeric_value:payload.numeric_value,unit:payload.unit}];delete payload.analyte_code;delete payload.analyte_name;delete payload.numeric_value;delete payload.unit;routes.lab='lab-samples'}try{const saved=await api(`api/v1/${routes[state.entry]}?year=${state.year}`,{method:'POST',body:JSON.stringify(payload)});for(const file of attachments){const data=new FormData();data.set('file',file);const response=await fetch(`api/v1/attachments/${attachmentTypes[state.entry]}/${saved.id}`,{method:'POST',body:data});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).detail||'Record saved, but a photo could not be attached')}$('entryDialog').close();toast(attachments.length?'Saved with photo evidence':'Saved');loadAll()}catch(error){toast(error.message)}}
async function submitWorkbookImport(commit){const form=$('workbookImportForm'),result=$('workbookImportResult'),data=new FormData(form);if(![...data.values()].some(value=>value instanceof File&&value.size)){toast('Choose at least one workbook');return}if(commit&&!confirm('Import these workbooks into MariaDB now? Continue only because the Home Assistant backup completed successfully.'))return;data.set('commit',commit?'true':'false');data.set('confirmation',commit?'BACKUP VERIFIED':'');result.hidden=false;result.classList.remove('error');result.textContent=commit?'Importing…':'Checking workbooks…';try{const response=await fetch('api/v1/admin/import-workbooks',{method:'POST',body:data});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.detail||`Import failed (${response.status})`);const lines=[commit?'Import completed.':'Check completed — no database rows changed.'];for(const [name,report] of Object.entries(payload.reports||{})){lines.push(`\n${name.replace('_',' & ')}`);for(const [key,value] of Object.entries(report.counts||{}))lines.push(`${key.replaceAll('_',' ')}: ${value}`);if((report.warnings||[]).length)lines.push(`Warnings: ${report.warnings.join('; ')}`)}result.textContent=lines.join('\n');if(commit)loadAll()}catch(error){result.classList.add('error');result.textContent=error.message}}
document.querySelectorAll('.tabs button').forEach(button=>button.onclick=()=>{document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b===button));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${button.dataset.view}`));if(button.dataset.view==='weather')setTimeout(()=>renderWeather(),0);if(button.dataset.view==='lab')setTimeout(()=>drawLabChart(),0);if(button.dataset.view==='finance')setTimeout(()=>drawFinanceChart(state.finance?.monthly||[]),0)});document.querySelectorAll('[data-open]').forEach(button=>button.onclick=()=>openEntry(button.dataset.open));document.querySelectorAll('[data-task-filter]').forEach(button=>button.onclick=()=>{state.taskFilter=button.dataset.taskFilter;document.querySelectorAll('[data-task-filter]').forEach(b=>b.classList.toggle('active',b===button));renderTasks()});document.querySelectorAll('[data-close-dialog]').forEach(button=>button.onclick=closeEntry);$('entryDialog')?.addEventListener('click',event=>{if(event.target===$('entryDialog'))closeEntry()});$('entryDialog')?.addEventListener('close',()=>{if($('entryForm'))$('entryForm').reset();if($('formFields'))$('formFields').replaceChildren();state.entry=null});if($('entryForm'))$('entryForm').onsubmit=saveEntry;if($('refresh'))$('refresh').onclick=loadAll;if($('todayDate'))$('todayDate').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});document.querySelectorAll('[data-record]').forEach(button=>button.onclick=()=>openRecords(button.dataset.record));document.querySelectorAll('[data-close-record]').forEach(button=>button.onclick=()=>$('recordDialog').close());document.querySelectorAll('[data-close-lab]').forEach(button=>button.onclick=()=>$('labDialog').close());if($('weatherMeasure'))$('weatherMeasure').onchange=drawWeatherComparison;if($('labSearch'))$('labSearch').oninput=()=>{const query=$('labSearch').value.trim().toLowerCase();document.querySelectorAll('[data-lab-sample]').forEach(node=>node.hidden=!node.textContent.toLowerCase().includes(query))};if($('intakeForm'))$('intakeForm').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.target);try{const response=await fetch('api/v1/intake/upload',{method:'POST',body:data});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.detail||'Upload failed');toast('Uploaded to the review inbox');event.target.reset();await loadAll()}catch(error){toast(error.message)}};if($('assistantForm'))$('assistantForm').onsubmit=async event=>{event.preventDefault();const answer=$('assistantAnswer'),button=event.submitter;button.disabled=true;answer.hidden=false;answer.textContent='Reviewing current vineyard data…';try{const result=await api('api/v1/assistant/ask',{method:'POST',body:JSON.stringify({question:new FormData(event.target).get('question')})});answer.textContent=result.configured?result.answer:result.message}catch(error){answer.textContent=error.message}finally{button.disabled=false}};if($('weatherImportForm'))$('weatherImportForm').onsubmit=async event=>{event.preventDefault();const status=$('weatherImportStatus'),data=new FormData(event.target);status.textContent='Importing weather history…';try{const response=await fetch('api/v1/weather/import-history',{method:'POST',body:data});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.detail||'Weather import failed');status.textContent=`Imported ${payload.imported} daily records; ${payload.skipped} non-data rows skipped.`;event.target.reset();await loadAll()}catch(error){status.textContent=error.message}};if($('pullFatture'))$('pullFatture').onclick=async()=>{const button=$('pullFatture');button.disabled=true;$('fattureStatus').textContent='Pulling authoritative records…';try{const result=await api('api/v1/finance/fattureincloud/pull',{method:'POST',body:'{}'});$('fattureStatus').textContent=result.configured?`Updated: ${Object.values(result.counts).reduce((a,b)=>a+b,0)} records checked`:result.message;if(result.configured)await loadAll()}catch(error){$('fattureStatus').textContent=error.message}finally{button.disabled=false}};setupYears();loadAll();
document.querySelectorAll('.tabs button').forEach(button=>button.addEventListener('click',()=>{const view=button.dataset.view;if(view==='lab')setTimeout(()=>{drawLabChart();renderLabTrends()},0);if(view==='harvest')setTimeout(()=>renderGrapes(),0);if(view==='projections')setTimeout(()=>renderProjections(),0);if(view==='olives')setTimeout(()=>renderOlives(),0)}));
if($('checkWorkbooks'))$('checkWorkbooks').onclick=()=>submitWorkbookImport(false);if($('commitWorkbooks'))$('commitWorkbooks').onclick=()=>submitWorkbookImport(true);
